{
  "name": "stream-broadcast-server",
  "version": "1.0.0",
  "private": true,
  "description": "Node.js server that broadcasts a readable stream and reliably unpipes it from every destination",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  }
}

/**
 * Returns every destination currently piped from `state`, normalised to an
 * array. Node stores a single pipe directly and multiple pipes as an array.
 */
function destinationsOf(state) {
  if (!state || !state.pipes) return []
  return Array.isArray(state.pipes) ? [...state.pipes] : [state.pipes]
}

/**
 * Reliably detaches a readable stream from *all* of its destinations.
 *
 * Node's `readable.unpipe()` with no argument detaches every destination, but
 * it iterates the live `state.pipes` collection. If an `'unpipe'` listener (or
 * a `'close'`/`'end'` handler) adds a new pipe while we are tearing down, that
 * destination can survive the call. This helper repeatedly snapshots and
 * detaches destinations until the pipes collection is empty, then falls back
 * to Node's no-argument `unpipe()` as a final backstop.
 *
 * @param {import('node:stream').Readable} source
 * @returns {import('node:stream').Readable} the same source, for chaining
 */
export function unpipeAll(source) {
  if (!source || typeof source.unpipe !== 'function') {
    throw new TypeError('unpipeAll requires a Readable stream')
  }

  const state = source._readableState

  // Bound the retries so a listener that perpetually re-pipes cannot spin
  // forever; 1024 passes is far more than any legitimate fan-out.
  let passes = 0
  while (destinationsOf(state).length > 0 && passes < 1024) {
    for (const destination of destinationsOf(state)) {
      source.unpipe(destination)
    }
    passes += 1
  }

  // Backstop for any destination Node tracks that we could not see above.
  source.unpipe()

  return source
}

export default unpipeAll

import http from 'node:http'
import { Readable } from 'node:stream'
import { unpipeAll } from './stream-utils.js'

const PORT = Number(process.env.PORT) || 3000

/**
 * A shared source stream that emits one timestamped line per second. Every
 * connected client is piped from this single readable, so it is the stream we
 * must be able to unpipe from all destinations on demand.
 */
function createTicker(intervalMs = 1000) {
  let seq = 0
  let timer = null

  const stream = new Readable({
    read() {
      if (timer) return
      timer = setInterval(() => {
        seq += 1
        stream.push(`event ${seq} ${new Date().toISOString()}\n`)
      }, intervalMs)
      timer.unref?.()
    },
  })

  stream.once('close', () => {
    if (timer) clearInterval(timer)
    timer = null
  })

  return stream
}

const ticker = createTicker()

function json(res, status, body) {
  const payload = JSON.stringify(body)
  res.writeHead(status, {
    'content-type': 'application/json',
    'content-length': Buffer.byteLength(payload),
  })
  res.end(payload)
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`)

  if (req.method === 'GET' && url.pathname === '/stream') {
    res.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-cache',
      connection: 'keep-alive',
    })
    res.write(': connected\n\n')
    ticker.pipe(res)

    // When the client goes away, detach just this destination.
    res.once('close', () => {
      ticker.unpipe(res)
    })
    return
  }

  if (req.method === 'POST' && url.pathname === '/stream/detach') {
    const before = ticker._readableState?.pipes?.length ?? 0
    unpipeAll(ticker)
    const after = ticker._readableState?.pipes?.length ?? 0
    json(res, 200, { detached: before, remaining: after })
    return
  }

  if (req.method === 'GET' && url.pathname === '/health') {
    json(res, 200, { status: 'ok' })
    return
  }

  json(res, 404, { error: 'not found' })
})

server.listen(PORT, () => {
  console.log(`stream-broadcast-server listening on http://localhost:${PORT}`)
})

export { server, ticker, createTicker }

import test from 'node:test'
import assert from 'node:assert/strict'
import { Readable, Writable, PassThrough } from 'node:stream'
import { unpipeAll } from '../src/stream-utils.js'

function discard() {
  return new Writable({
    write(_chunk, _enc, callback) {
      callback()
    },
  })
}

test('detaches every destination from a shared source', () => {
  const source = new Readable({ read() {} })
  const a = discard()
  const b = discard()
  const c = discard()

  source.pipe(a)
  source.pipe(b)
  source.pipe(c)

  assert.equal(source._readableState.pipes.length, 3)

  const unpiped = []
  source.on('unpipe', (dest) => unpiped.push(dest))

  unpipeAll(source)

  assert.deepEqual(source._readableState.pipes, [])
  assert.equal(unpiped.length, 3)
  assert.deepEqual(new Set(unpiped), new Set([a, b, c]))
})

test('emits one unpipe event per destination', () => {
  const source = new Readable({ read() {} })
  const dest = discard()
  source.pipe(dest)

  let count = 0
  source.on('unpipe', () => {
    count += 1
  })

  unpipeAll(source)
  unpipeAll(source)

  assert.equal(count, 1)
})

test('is safe when no destinations are attached', () => {
  const source = new Readable({ read() {} })
  assert.doesNotThrow(() => unpipeAll(source))
  assert.deepEqual(source._readableState.pipes, [])
})

test('re-detaches destinations added during teardown', () => {
  const source = new Readable({ read() {} })
  const first = discard()
  const late = discard()
  source.pipe(first)

  let added = false
  source.on('unpipe', () => {
    if (!added) {
      added = true
      source.pipe(late)
    }
  })

  unpipeAll(source)

  assert.deepEqual(source._readableState.pipes, [])
  assert.equal(source.listenerCount('unpipe') > 0, true)
})

test('can unpipe a PassThrough mid-flow and keep reading locally', () => {
  const source = Readable.from(['one', 'two', 'three'])
  const dest = new PassThrough()
  source.pipe(dest)

  unpipeAll(source)

  assert.deepEqual(source._readableState.pipes, [])
  assert.equal(dest.readableEnded, false)
})

test('throws a TypeError for non-stream input', () => {
  assert.throws(() => unpipeAll(null), TypeError)
  assert.throws(() => unpipeAll({}), TypeError)
})

